155	
156	            // SAFETY: thread_handle is a valid handle to the current thread
157	            unsafe { SetThreadPriority(thread_handle, THREAD_PRIORITY_TIME_CRITICAL) }
158	                .context("thread priority")
159	                .log_err();
160	
161	            f();
162	        });
163	    }
