1495	        )));
1496	
1497	        return match WindowsPlatformInner::new(creation_context) {
1498	            Ok(inner) => {
1499	                let weak = Box::new(Rc::downgrade(&inner));
1500	                unsafe { set_window_long(hwnd, GWLP_USERDATA, Box::into_raw(weak) as isize) };
1501	                creation_context.inner = Some(Ok(inner));
1502	                unsafe { DefWindowProcW(hwnd, msg, wparam, lparam) }
1503	            }
1504	            Err(error) => {
1505	                creation_context.inner = Some(Err(error));
1506	                LRESULT(0)
1507	            }
1508	        };
1509	    }
